args.content:
/* Halcyon Threshold - Simple, clean styling */

:root {
    --color-bg: #fafafa;
    --color-text: #2a2a2a;
    --color-muted: #666;
    --color-accent: #1a5f7a;
    --color-accent-light: #e8f4f8;
    --max-width: 680px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    font-size: 18px;
    line-height: 1.6;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
    background: var(--color-bg);
    color: var(--color-text);
    padding: 2rem 1rem;
}

main {
    max-width: var(--max-width);
    margin: 0 auto;
}

header {
    margin-bottom: 3rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid #ddd;
}

h1 {
    font-size: 2.2rem;
    font-weight: 600;
    letter-spacing: -0.02em;
    margin-bottom: 0.3rem;
}

.tagline {
    font-size: 1.1rem;
    color: var(--color-muted);
    font-style: italic;
}

section {
    margin-bottom: 2.5rem;
}

h2 {
    font-size: 1.3rem;
    font-weight: 600;
    margin-bottom: 0.8rem;
    color: var(--color-accent);
}

p {
    margin-bottom: 1rem;
}

ul {
    margin-left: 1.2rem;
    margin-bottom: 1rem;
}

li {
    margin-bottom: 0.6rem;
}

a {
    color: var(--color-accent);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.2s;
}

a:hover {
    border-bottom-color: var(--color-accent);
}

footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid #ddd;
    font-size: 0.9rem;
    color: var(--color-muted);
}

@media (max-width: 480px) {
    html {
        font-size: 16px;
    }

    h1 {
        font-size: 1.8rem;
    }
}
